-- 53个餐厅/门店点位的地图参考坐标；不是53个食堂室内档口坐标。
-- 来源FFM MIT；源坐标系依据和转换记录见collection/round2/normalized-places.csv。
-- 已有坐标不覆盖；发现重名多候选即停止，避免错挂。
USE dafu_shike;
SET NAMES utf8mb4;
START TRANSACTION;
SET @d_map_count=(SELECT COUNT(*) FROM location WHERE name='玫瑰园食惠餐厅' AND deleted_at IS NULL);
SET @d_map_guard=IF(@d_map_count=1,'DO 0','SELECT * FROM information_schema.D_COLLECTED_PLACE_NOT_UNIQUE');
PREPARE d_map_stmt FROM @d_map_guard;
EXECUTE d_map_stmt;
DEALLOCATE PREPARE d_map_stmt;
SET @d_location=(SELECT id FROM location WHERE name='玫瑰园食惠餐厅' AND deleted_at IS NULL LIMIT 1);
INSERT INTO map_location(latitude,longitude,description) SELECT 26.0526024,119.1927543,'D采集FFM:qishan-009;GCJ02推定转换;非实测' WHERE (SELECT map_location_id FROM location WHERE id=@d_location) IS NULL AND NOT EXISTS(SELECT 1 FROM map_location WHERE description='D采集FFM:qishan-009;GCJ02推定转换;非实测');
UPDATE location SET map_location_id=(SELECT MIN(id) FROM map_location WHERE description='D采集FFM:qishan-009;GCJ02推定转换;非实测') WHERE id=@d_location AND map_location_id IS NULL;
